import io.swagger.v3.oas.annotations.media.ArraySchema;
import io.swagger.v3.oas.annotations.media.Schema;

import java.time.LocalDate;
import java.util.List;

@Schema(description = "Resultado da importacao e consolidacao ponderada da pesquisa")
public record PollImportResponseDTO(
        @Schema(description = "Identificador da pesquisa", example = "PESQ-2026-01")
        String pollId,
        @Schema(description = "Data da pesquisa", example = "2026-03-01")
        LocalDate pollDate,
        @Schema(description = "Populacao total usada na ponderacao", example = "12700000")
        long weightedPopulation,
        @ArraySchema(schema = @Schema(implementation = CandidateWeightedResultDTO.class,
                description = "Resultados ponderados por candidato"))
        List<CandidateWeightedResultDTO> candidates
) {
}

package com.diegoramos.konatus.pesquisaeleitoral.service.ibge;

import com.diegoramos.konatus.pesquisaeleitoral.domain.Municipality;
import com.diegoramos.konatus.pesquisaeleitoral.domain.State;
import com.diegoramos.konatus.pesquisaeleitoral.dto.ibgeDTO.IbgeMunicipalityResponseDTO;
import com.diegoramos.konatus.pesquisaeleitoral.dto.ibgeDTO.IbgeStateResponseDTO;
import com.diegoramos.konatus.pesquisaeleitoral.dto.ibgeDTO.IbgeSyncResultDTO;
import com.diegoramos.konatus.pesquisaeleitoral.repository.MunicipalityRepository;
import com.diegoramos.konatus.pesquisaeleitoral.repository.StateRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class IbgeServiceTest {

    @Mock
    private IbgeApiClient ibgeApiClient;

    @Mock
    private StateRepository stateRepository;

    @Mock
    private MunicipalityRepository municipalityRepository;

    @InjectMocks
    private IbgeService ibgeService;

    @Test
    void shouldNotPersistWhenIbgeDataIsUnchanged() {
        State state = State.create("Sao Paulo", "SP");
        Municipality municipality = Municipality.create("Campinas", 1_000, state);

        when(stateRepository.findAll()).thenReturn(List.of(state));
        when(municipalityRepository.findAllByState(state)).thenReturn(List.of(municipality));
        when(ibgeApiClient.getStates()).thenReturn(List.of(new IbgeStateResponseDTO(35L, "SP", "Sao Paulo")));
        when(ibgeApiClient.getMunicipalitiesByStateAcronym("SP"))
                .thenReturn(List.of(new IbgeMunicipalityResponseDTO(3509502L, "Campinas")));
        when(ibgeApiClient.getMunicipalityPopulationByCode(3509502L)).thenReturn(1_000);

        IbgeSyncResultDTO result = ibgeService.syncStatesAndMunicipalities(false);

        assertThat(result.statesCreated()).isZero();
        assertThat(result.statesUpdated()).isZero();
        assertThat(result.municipalitiesCreated()).isZero();
        assertThat(result.forced()).isFalse();

        verify(stateRepository, never()).save(any(State.class));
        verify(municipalityRepository, never()).saveAll(any());
    }

    @Test
    void shouldCreateStateAndMunicipalityWhenNotPresentLocally() {
        State persistedState = State.create("Acre", "AC");

        when(stateRepository.findAll()).thenReturn(List.of());
        when(stateRepository.save(any(State.class))).thenReturn(persistedState);
        when(municipalityRepository.findAllByState(persistedState)).thenReturn(List.of());
        when(ibgeApiClient.getStates()).thenReturn(List.of(new IbgeStateResponseDTO(12L, "AC", "Acre")));
        when(ibgeApiClient.getMunicipalitiesByStateAcronym("AC"))
                .thenReturn(List.of(new IbgeMunicipalityResponseDTO(1200401L, "Rio Branco")));
        when(ibgeApiClient.getMunicipalityPopulationByCode(1200401L)).thenReturn(364_756);

        IbgeSyncResultDTO result = ibgeService.syncStatesAndMunicipalities(false);

        assertThat(result.statesCreated()).isEqualTo(1);
        assertThat(result.statesUpdated()).isZero();
        assertThat(result.municipalitiesCreated()).isEqualTo(1);

        verify(stateRepository).save(any(State.class));
        verify(municipalityRepository).saveAll(any());
    }
}

package com.diegoramos.konatus.pesquisaeleitoral.service.poll.weighting;

import com.diegoramos.konatus.pesquisaeleitoral.domain.Candidate;
import com.diegoramos.konatus.pesquisaeleitoral.domain.Municipality;
import com.diegoramos.konatus.pesquisaeleitoral.domain.State;
import com.diegoramos.konatus.pesquisaeleitoral.service.poll.result.CandidateWeightedResult;
import org.junit.jupiter.api.Test;
import org.springframework.test.util.ReflectionTestUtils;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.stream.Collectors;

import static org.assertj.core.api.Assertions.assertThat;

class PollWeightAccumulatorTest {

    @Test
    void shouldCalculateWeightedAverageCorrectly() {
        PollWeightAccumulator accumulator = new PollWeightAccumulator();

        State state = State.create("Sao Paulo", "SP");
        setId(state, UUID.fromString("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa"));

        Municipality municipalityA = Municipality.create("Cidade A", 1_000, state);
        setId(municipalityA, UUID.fromString("bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb"));

        Municipality municipalityB = Municipality.create("Cidade B", 3_000, state);
        setId(municipalityB, UUID.fromString("cccccccc-cccc-cccc-cccc-cccccccccccc"));

        Candidate candidate1 = Candidate.create("Maria", "PA");
        setId(candidate1, UUID.fromString("11111111-1111-1111-1111-111111111111"));

        Candidate candidate2 = Candidate.create("Joao", "PB");
        setId(candidate2, UUID.fromString("22222222-2222-2222-2222-222222222222"));

        accumulator.registerStateMunicipalities(state, List.of(municipalityA, municipalityB));

        accumulator.addSample(state, municipalityA, candidate1, new BigDecimal("60"));
        accumulator.addSample(state, municipalityA, candidate2, new BigDecimal("40"));
        accumulator.addSample(state, municipalityB, candidate1, new BigDecimal("30"));
        accumulator.addSample(state, municipalityB, candidate2, new BigDecimal("70"));

        long totalPopulation = accumulator.totalPopulation();
        List<CandidateWeightedResult> results = accumulator.buildResults(totalPopulation);

        Map<UUID, BigDecimal> byCandidate = results.stream()
                .collect(Collectors.toMap(CandidateWeightedResult::candidateId, CandidateWeightedResult::weightedPercentage));

        assertThat(totalPopulation).isEqualTo(4_000);
        assertThat(byCandidate.get(candidate1.getId())).isEqualByComparingTo("37.50");
        assertThat(byCandidate.get(candidate2.getId())).isEqualByComparingTo("62.50");
    }

    private static void setId(Object entity, UUID id) {
        ReflectionTestUtils.setField(entity, "id", id);
    }
}
